-- Three focused original mock-exam corrections. Existing exam snapshots are unchanged.

CREATE TABLE IF NOT EXISTS mock_exam_content_revision (
 revision_key VARCHAR(80) PRIMARY KEY,
 question_id BIGINT NOT NULL,
 before_content JSON NOT NULL,
 after_content JSON NOT NULL,
 evidence_urls JSON NOT NULL,
 applied_at DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DROP TEMPORARY TABLE IF EXISTS lexaid_formal_review_candidates;
CREATE TEMPORARY TABLE lexaid_formal_review_candidates (
 revision_key VARCHAR(80) PRIMARY KEY, question_id BIGINT NOT NULL,
 before_content JSON NOT NULL, after_content JSON NOT NULL, evidence_urls JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO lexaid_formal_review_candidates VALUES

('2026-11-12-formal-8000004',8000004,CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT( USING utf8mb4) AS JSON)),
('2026-11-12-formal-8000006',8000006,CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT(0x5b2268747470733a2f2f7777772e7370702e676f762e636e2f7370702f7a64677a2f3230313831302f7432303138313032375f3339363831382e7368746d6c225d USING utf8mb4) AS JSON)),
('2026-11-12-formal-8000008',8000008,CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT( USING utf8mb4) AS JSON),CAST(CONVERT(0x5b2268747470733a2f2f7777772e73616d722e676f762e636e2f7a772f7a667878676b2f66647a64676b6e722f747a7362732f6172742f323032332f6172745f33373132666266616165643934326233623662363666313464353238383732332e68746d6c225d USING utf8mb4) AS JSON));

START TRANSACTION;

INSERT INTO mock_exam_content_revision(revision_key,question_id,before_content,after_content,evidence_urls) SELECT c.revision_key,c.question_id,c.before_content,c.after_content,c.evidence_urls FROM lexaid_formal_review_candidates c JOIN mock_exam_bank q ON q.id=c.question_id WHERE BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(c.before_content AS CHAR) ON DUPLICATE KEY UPDATE revision_key=mock_exam_content_revision.revision_key;

UPDATE mock_exam_bank q JOIN lexaid_formal_review_candidates c ON c.question_id=q.id JOIN mock_exam_content_revision r ON r.revision_key=c.revision_key AND r.question_id=q.id SET q.stem=JSON_UNQUOTE(JSON_EXTRACT(c.after_content,'$.stem')),q.reference_answer=JSON_UNQUOTE(JSON_EXTRACT(c.after_content,'$.answer')) WHERE BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(c.before_content AS CHAR) AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(c.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(c.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(c.evidence_urls AS CHAR);

SET @lexaid_formal_changed=ROW_COUNT();

UPDATE mock_exam_content_revision r JOIN lexaid_formal_review_candidates c ON c.revision_key=r.revision_key AND c.question_id=r.question_id JOIN mock_exam_bank q ON q.id=c.question_id SET r.applied_at=COALESCE(r.applied_at,NOW()) WHERE BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(c.after_content AS CHAR) AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(c.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(c.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(c.evidence_urls AS CHAR);

COMMIT;

SELECT @lexaid_formal_changed AS changed_this_run;

SELECT c.question_id,CASE WHEN BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(c.after_content AS CHAR) AND r.applied_at IS NOT NULL AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(c.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(c.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(c.evidence_urls AS CHAR) THEN 'APPLIED_OR_ALREADY_APPLIED' ELSE 'SKIPPED_CONTENT_OR_ARCHIVE_MISMATCH' END AS result FROM lexaid_formal_review_candidates c LEFT JOIN mock_exam_bank q ON q.id=c.question_id LEFT JOIN mock_exam_content_revision r ON r.revision_key=c.revision_key AND r.question_id=c.question_id ORDER BY c.question_id;

DROP TEMPORARY TABLE lexaid_formal_review_candidates;
